using Azure.Storage.Blobs;

var connectionString = "DefaultEndpointsProtocol=https;AccountName=...";
var blobService = new BlobServiceClient(connectionString);

var container = blobService.GetBlobContainerClient("uploads");
await container.CreateIfNotExistsAsync();

var blob = container.GetBlobClient("report-2024.pdf");
await blob.UploadAsync("report.pdf");
